/* ============================================================
 * 数据适配层：优先 fetch data/*.csv 真实数据，失败回退内置常量。
 * 说明：内置常量与 summary/*.csv 内容一致（由 gen_data_js.py 生成）。
 * ============================================================ */
function _parseCSV(text) {
  const rows = [];
  let row = [], field = '', inQ = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQ) {
      if (c === '"') { if (text[i + 1] === '"') { field += '"'; i++; } else inQ = false; }
      else field += c;
    } else if (c === '"') { inQ = true; }
    else if (c === ',') { row.push(field); field = ''; }
    else if (c === '\n') { row.push(field); rows.push(row); row = []; field = ''; }
    else if (c !== '\r') { field += c; }
  }
  if (field !== '' || row.length) { row.push(field); rows.push(row); }
  return rows.filter(r => r.length > 0 && (r.length > 1 || r[0] !== ''));
}
function _rowsToObjects(rows) {
  if (!rows.length) return [];
  const header = rows[0].map(h => String(h).replace(/^\uFEFF/, ''));
  return rows.slice(1).map(r => {
    const o = {};
    header.forEach((h, i) => { o[h] = (r[i] !== undefined) ? String(r[i]) : ''; });
    return o;
  });
}
function _f(v) { if (v === '' || v === null || v === undefined) return null; const n = parseFloat(v); return isNaN(n) ? null : n; }
function _i(v) { if (v === '' || v === null || v === undefined) return null; const n = parseInt(v, 10); return isNaN(n) ? null : n; }
function _tokens(s) {
  if (!s) return [];
  const out = [];
  s.split(';').forEach(seg => {
    seg = (seg || '').trim();
    if (!seg) return;
    const w = seg.split(':')[0].trim().toLowerCase();
    if (w) out.push(w);
  });
  return Array.from(new Set(out)).sort();
}
function _splitList(s) {
  if (!s) return [];
  const block = ['none', 'nan', 'null', '数据不足', '待人工'];
  const out = [];
  s.split(';').forEach(seg => {
    seg = (seg || '').trim();
    if (!seg || block.indexOf(seg.toLowerCase()) >= 0) return;
    out.push(seg);
  });
  return out;
}

const DATA_SOURCES = {
  screenwriting: 'data/screenwriting_vs_heat.csv',
  featureCorr: 'data/feature_heat_correlation.csv',
  corrMatrix: 'data/correlation_matrix.csv',
  highLowMeans: 'data/high_low_numeric_means.csv',
  highLowShare: 'data/high_low_group_share.csv',
  plotTypeCorr: 'data/情节点类型_heat_correlation.csv',
  conflictWordCorr: 'data/冲突信号词_heat_correlation.csv',
  majorEventCorr: 'data/大事件信号词_heat_correlation.csv',
  conflictBins: 'data/冲突密度分档_heat.csv',
  hookEvidence: 'data/hook_conflict_heat_evidence.csv',
};

async function _fetchCSV(path) {
  const res = await fetch(path);
  if (!res.ok) throw new Error('HTTP ' + res.status + ': ' + path);
  return _rowsToObjects(_parseCSV(await res.text()));
}

function buildFromRows(screenwriting, featureCorr, corrMatrix, highLowMeans, highLowShare,
                       plotTypeCorr, conflictWordCorr, majorEventCorr, conflictBins, hookEvidence) {
  const hookMap = {};
  hookEvidence.forEach(r => {
    hookMap[r['视频ID']] = {
      hookDensity: _f(r['强钩子事件密度_每10分钟']),
      insultDensity: _f(r['侮辱谎言憎恨冲突密度_每10分钟']),
      words: _tokens(r['强钩子示例词']).concat(_tokens(r['冲突示例词'])),
    };
  });
  const dramas = screenwriting.map(r => {
    const hk = hookMap[r['视频ID']] || { hookDensity: 0, insultDensity: 0, words: [] };
    return {
      rank: _i(r['排名']), name: r['剧名'], vid: r['视频ID'],
      duration: r['时长_原始'] || '', views: _i(r['播放量']),
      likeRate: _f(r['点赞率']), commentRate: _f(r['评论率']),
      trend: _f(r['Google_Trends平均热度']), heat: _f(r['综合传播热度']),
      theme: r['题材母题_主标签'] || '其他',
      structure: (r['叙事结构_线性非线性'] === '线性') ? '线性' : '非线性',
      conflictDensity: _f(r['冲突密度_次每分钟']), conflictEvents: _i(r['冲突事件数']),
      chanceFreq: _f(r['偶然事件频率_每10分钟']), majorFreq: _f(r['大事件频率_每10分钟']),
      chanceEvents: _i(r['偶然事件数']), majorEvents: _i(r['大事件数']), mainChars: _i(r['主要人物数']),
      plotPoints: _i(r['情节点数量']), flaws: _i(r['叙事缺陷数量']),
      cutFreq: _f(r['镜头切换频率_次每秒']), dialogue: _f(r['对话密度_说话占比']),
      speechRate: _f(r['语速_词每分钟']), twistDensity: _f(r['情节转折密度_次每分钟']),
      hookDensity: hk.hookDensity, insultDensity: hk.insultDensity, words: hk.words,
      tonePrimary: r['情感基调主标签'] || '',
      toneTags: _splitList(r['情感基调标签']),
      communityScore: _i(r['情感共同体构建评分']),
      communityIssues: _splitList(r['触及社会议题']),
      valueScore: _i(r['情感价值感知评分']),
    };
  });
  const mk = (rows2, mapFn) => rows2.map(mapFn);
  const sig = rows2 => rows2.map(r => ({
    term: r['术语'], dim: r['维度'], n_dramas: _i(r['出现剧数']), n: _i(r['有效样本']),
    rho: _f(r['Spearman_rho']), p: _f(r['Spearman_p']), pearson: _f(r['Pearson_r']),
    pearsonP: _f(r['Pearson_p']), highMean: _f(r['高组每10分钟均值']),
    lowMean: _f(r['低组每10分钟均值']), diff: _f(r['均值差']),
  }));
  const hdr = Object.keys(corrMatrix[0] || {}).filter(k => k && k !== '');
  const labels = hdr;
  const matrix = corrMatrix.map(r => labels.map(h => _f(r[h])));
  return {
    dramas,
    featureCorr: mk(featureCorr, r => ({ feature: r['特征'], field: r['类型'], n: _i(r['有效样本量']),
      rho: _f(r['Spearman_rho']), p: _f(r['Spearman_p']), pearson: _f(r['Pearson_r']), pearsonP: _f(r['Pearson_p']) })),
    corrMatrix: { labels, matrix },
    highLowMeans: mk(highLowMeans, r => ({ feature: r['特征'], high: _f(r['高组均值']), low: _f(r['低组均值']), diff: _f(r['均值差']) })),
    highLowShare: mk(highLowShare, r => ({ category: r['类别'], high: _f(r['高热度组占比']), low: _f(r['低热度组占比']), diff: _f(r['占比差']) })),
    plotTypeCorr: sig(plotTypeCorr),
    conflictWordCorr: sig(conflictWordCorr),
    majorEventCorr: sig(majorEventCorr),
    conflictBins: conflictBins.map(r => ({ bin: r['密度分档'], count: _i(r['剧数']),
      meanDensity: _f(r['冲突密度均值']), meanHeat: _f(r['综合热度均值']), medianHeat: _f(r['综合热度中位']) })),
    threeDims: BUILTIN_DATA.threeDims,
    examples: BUILTIN_DATA.examples,
  };
}

const dataAdapter = {
  source: 'builtin',
  async load() {
    try {
      const [a, b, c, d, e, f2, g, h, i, j] = await Promise.all([
        _fetchCSV(DATA_SOURCES.screenwriting),
        _fetchCSV(DATA_SOURCES.featureCorr),
        _fetchCSV(DATA_SOURCES.corrMatrix),
        _fetchCSV(DATA_SOURCES.highLowMeans),
        _fetchCSV(DATA_SOURCES.highLowShare),
        _fetchCSV(DATA_SOURCES.plotTypeCorr),
        _fetchCSV(DATA_SOURCES.conflictWordCorr),
        _fetchCSV(DATA_SOURCES.majorEventCorr),
        _fetchCSV(DATA_SOURCES.conflictBins),
        _fetchCSV(DATA_SOURCES.hookEvidence),
      ]);
      this.source = 'real';
      return buildFromRows(a, b, c, d, e, f2, g, h, i, j);
    } catch (err) {
      console.warn('[dataAdapter] 回退内置示例数据：', err && err.message ? err.message : err);
      this.source = 'builtin';
      return BUILTIN_DATA;
    }
  }
};


